const b = $input.item.json.body || {};
const inspected = Number(b.units_inspected);
const defective = Number(b.units_defective);
const valid = Number.isFinite(inspected) && Number.isFinite(defective) && inspected > 0 && defective >= 0 && defective <= inspected;
const rate = valid ? Math.round((defective / inspected) * 10000) / 100 : null;
return { json: {
  batch_id: b.batch_id || 'unknown',
  product_line: b.product_line || 'unknown',
  timestamp: b.timestamp || new Date().toISOString(),
  units_inspected: b.units_inspected, units_defective: b.units_defective,
  defect_types: b.defect_types || '',
  inspector_notes: b.inspector_notes || '',
  defect_rate_pct: rate,
  input_valid: valid,
  warn_limit_pct: 2,   // ILLUSTRATIVE - set your own tolerance
  hard_limit_pct: 5    // ILLUSTRATIVE - set your own tolerance
} };

