const out = $input.item.json.output || {};
const base = $('Calculate Defect Rate').item.json;
const allowed = ['Release', 'Hold for Inspection', 'Reject Batch'];
const rank = (d) => allowed.indexOf(d);
let disp = out.disposition;
let guard = 'passed';
if (!base.input_valid) { disp = 'Hold for Inspection'; guard = 'failed: invalid inspection data, held for human check'; }
else {
  if (!allowed.includes(disp)) { disp = 'Hold for Inspection'; guard = 'failed: invalid AI disposition, held for human check'; }
  if (base.defect_rate_pct >= base.hard_limit_pct && rank(disp) < rank('Hold for Inspection')) { disp = 'Hold for Inspection'; guard = 'adjusted: defect rate above hard limit, cannot be released'; }
}
return { json: {
  ...base,
  disposition: disp,
  likely_defect_pattern: out.likely_defect_pattern || 'n/a',
  root_cause_hypotheses: out.root_cause_hypotheses || 'n/a',
  corrective_actions: out.corrective_actions || 'Manual review required',
  explanation: out.explanation || '',
  guard_check: guard,
  needs_attention: disp !== 'Release'
} };

